"""Curated full-text extractions for the 2020--2024 resolution artifact.

Every non-reported item is represented literally as ``not reported``.  The maps
below were prepared from the locally preserved complete texts named in the
screening artifact; they are not generated from titles alone.
"""

from __future__ import annotations


CAUTION = "The total is a compact audit aid, not a ranking; interpret every dimension against the paper's claim and study design."


def _blank(columns: list[str], values: dict[str, str]) -> dict[str, str]:
    row = {column: "not reported" for column in columns}
    row.update(values)
    assert set(row) == set(columns)
    return row


def _q(dimensions: list[str], paper_id: str, title: str, classification: str, values: list[tuple[int, str]]) -> dict:
    assert len(dimensions) == len(values) == 12
    mapped = {name: {"score": score, "rationale": rationale} for name, (score, rationale) in zip(dimensions, values)}
    return {
        "Paper ID": paper_id,
        "Title": title,
        "Core or adjacent classification": classification,
        "Dimension scores": mapped,
        "Total": sum(item["score"] for item in mapped.values()),
        "Interpretation caution": CAUTION,
    }


